    if (maps & 1u)
        result.x = coatRoughnessTexture.SampleLevel(textureSampler, maps & 4u ? uv1 : uv0, 0).r;
    if (maps & 2u)
        result.y = coatRoughnessTexture.SampleLevel(textureSampler, maps & 8u ? uv1 : uv0, 0).b;
